examples.code:
figure
patch([0 1 0.5], [0 0 1], 'g')
hold on
V = [2 0; 3 0; 3 1; 2 1];
F = [1 2 3; 1 3 4];
p = patch('Faces', F, 'Vertices', V, 'FaceColor', 'b', 'FaceAlpha', 0.5);
axis equal

P = polyshape([0 4 4 0], [0 0 3 3]);
H = polyshape([1 2 2 1], [1 1 2 2]);
D = subtract(P, H);
perimeter(P)
perimeter(D)

x = [0 1 1 0 0.5]';
y = [0 0 1 1 0.5]';
DT = delaunayTriangulation(x, y);
[ti, bc] = pointLocation(DT, [0.9 0.5; 5 5])

P = polyshape([0 4 4 0], [0 0 3 3]);
rounded = polybuffer(P, 1);
mitered = polybuffer(P, 1, 'JointType', 'miter');
fprintf('%.4f\n', area(rounded), area(mitered))

P = polyshape([0 1 1 0 NaN 3 5 5 3], [0 0 1 1 NaN 0 0 2 2]);
R = regions(P);
numel(R)

P = polyshape([0 4 4 0], [0 0 3 3]);
B = addboundary(P, [5 6 6 5], [0 0 1 1]);
area(B)
R = rmboundary(B, 2);
area(R)

P = polyshape([0 4 4 0], [0 0 3 3]);
H = polyshape([1 2 2 1], [1 1 2 2]);
D = subtract(P, H);
R = rmholes(D);
[area(D) area(R)]
R.NumHoles

A = polyshape([0 2 2 0], [0 0 2 2]);
B = addboundary(A, [5 5.02 5.02 5], [0 0 2 2]);
C = rmslivers(B, 0.05);
[area(B) area(C)]
C.NumRegions

Q = polyshape([0 1 1 0], [0 0 1 1]);
R = rotate(Q, 90, [0.5 0.5]);
R.Vertices
area(R)

P = polyshape([0 2 2 0], [0 0 1 1]);
S = scale(P, [3 1], [0 0]);
S.Vertices
are = [area(P) area(S)]

P = polyshape([0 1 1 0 NaN 3 5 5 3], [0 0 1 1 NaN 0 0 2 2]);
S = sortboundaries(P, 'area', 'descend');
S.Vertices

P = polyshape([0 1 1 0 NaN 3 5 5 3], [0 0 1 1 NaN 0 0 2 2]);
S = sortregions(P, 'area', 'ascend');
S.Vertices

P = [0 0 0; 1 0 0; 0 1 0; 0 0 1];
T = [1 3 2; 1 2 4; 1 4 3; 2 3 4];
stlwrite(triangulation(T, P), 'tet.stl');
TR = stlread('tet.stl');
size(TR.Points)
size(TR.ConnectivityList)

P = [0 0 0; 1 0 0; 0 1 0; 0 0 1];
T = [1 3 2; 1 2 4; 1 4 3; 2 3 4];
tr = triangulation(T, P);
stlwrite(tr, 'tet_bin.stl');
stlwrite(tr, 'tet_txt.stl', 'text');
d1 = dir('tet_bin.stl');
disp(d1.bytes)

P = polyshape([0 4 4 0], [0 0 3 3]);
H = polyshape([1 2 2 1], [1 1 2 2]);
D = subtract(P, H);
D.NumHoles
area(D)

P = [0 0 0; 1 0 0; 0 1 0; 0 0 1];
shp = alphaShape(P(:,1), P(:,2), P(:,3));
surfaceArea(shp)
volume(shp)
